mapper.update:
UPDATE ics21_checklist_l_class
   SET ics21_checklist_l_class_nm = #{req.checklistLClassName},
       ics21_use_yn               = #{req.useYn},
       ics21_note                 = #{req.note},
       ics21_seq                  = #{req.seq},
       ics21_close_date           = #{req.closeDate}
 WHERE ics21_checklist_l_class_id = #{req.checklistLClassId}
   AND ics21_company_id           = #{companyId}

mapper.insert:
WITH upsert AS ( UPDATE ics22_checklist_l_class_company
                    SET ics22_close_date = #{closeDate},
                        ics22_use_yn     = #{useYn}
                  WHERE ics22_company_id          = #{companyId}
                    AND ics22_checklist_l_class_id = #{checklistLClassId}
              RETURNING * )
INSERT INTO ics22_checklist_l_class_company
       ( ics22_checklist_l_class_company_id, ics22_company_id, ics22_checklist_l_class_id, ics22_use_yn, ics22_note, ics22_close_date )
SELECT f_create_seq(), #{companyId}, #{checklistLClassId}, #{useYn}, NULL, #{closeDate}
 WHERE NOT EXISTS ( SELECT * FROM upsert )

